'use client'

import * as React from 'react'

import { cn } from '@/lib/utils'

export interface WorkspaceNavItem {
  id: string
  label: string
  icon?: React.ReactNode
  badge?: string
}

export interface WorkspaceNavGroup {
  id: string
  label: string
  items: WorkspaceNavItem[]
}

export interface WorkspaceSidebarProps {
  organizationName: string
  organizationMeta?: string
  groups: WorkspaceNavGroup[]
  activeItemId?: string
  isCollapsed?: boolean
  onNavigate?: (itemId: string) => void
  onToggle?: () => void
  className?: string
}

function CollapseIcon() {
  return (
    <svg aria-hidden viewBox="0 0 20 20" className="size-4 fill-none stroke-current" strokeWidth="1.7">
      <path d="M12.5 5 7.5 10l5 5" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M4 3.5h12v13H4z" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

export function WorkspaceSidebar({
  organizationName,
  organizationMeta,
  groups,
  activeItemId,
  isCollapsed = false,
  onNavigate,
  onToggle,
  className
}: WorkspaceSidebarProps) {
  return (
    <aside
      aria-label="Workspace navigation"
      aria-hidden={isCollapsed}
      className={cn(
        'flex h-dvh w-64 shrink-0 flex-col border-r bg-card text-card-foreground transition-[opacity,transform] duration-200 ease-out',
        isCollapsed && '-translate-x-3 opacity-0',
        className
      )}
    >
      <div className="flex h-[52px] shrink-0 items-center gap-2.5 border-b px-3">
        <div className="grid size-7 shrink-0 place-items-center rounded-md bg-foreground text-[11px] font-bold tracking-tight text-background">
          T<span className="sr-only">TigerERP</span>
        </div>
        <div className="min-w-0 flex-1">
          <p className="truncate text-[13px] font-semibold leading-4">{organizationName}</p>
          {organizationMeta && <p className="truncate text-[11px] leading-4 text-muted-foreground">{organizationMeta}</p>}
        </div>
        <button
          type="button"
          onClick={onToggle}
          className="grid size-7 place-items-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          aria-label="Hide sidebar"
        >
          <CollapseIcon />
        </button>
      </div>

      <nav className="flex min-h-0 flex-1 flex-col overflow-y-auto px-2 py-3">
        {groups.map((group, groupIndex) => (
          <div
            key={group.id}
            className={cn('mb-5', groupIndex === groups.length - 1 && groups.length > 1 && 'mt-auto mb-0')}
          >
            <p className="mb-1.5 px-2 text-[10px] font-semibold uppercase tracking-[0.12em] text-muted-foreground/80">
              {group.label}
            </p>
            <div className="space-y-0.5">
              {group.items.map((item) => {
                const isActive = item.id === activeItemId

                return (
                  <button
                    key={item.id}
                    type="button"
                    aria-current={isActive ? 'page' : undefined}
                    onClick={() => onNavigate?.(item.id)}
                    className={cn(
                      'group flex h-8 w-full items-center gap-2.5 rounded-md px-2 text-left text-[13px] font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                      isActive
                        ? 'bg-accent text-accent-foreground'
                        : 'text-muted-foreground hover:bg-accent/70 hover:text-foreground'
                    )}
                  >
                    <span className={cn('grid size-4 shrink-0 place-items-center', isActive && 'text-info')}>{item.icon}</span>
                    <span className="min-w-0 flex-1 truncate">{item.label}</span>
                    {item.badge && (
                      <span className="financial-nums rounded-sm bg-muted px-1.5 py-0.5 text-[10px] font-semibold text-muted-foreground">
                        {item.badge}
                      </span>
                    )}
                  </button>
                )
              })}
            </div>
          </div>
        ))}
      </nav>
    </aside>
  )
}
