import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'

import { cn } from '@/lib/utils'

const badgeVariants = cva(
  'inline-flex h-5 w-fit items-center gap-1.5 whitespace-nowrap rounded-sm border px-1.5 text-[11px] font-semibold leading-none',
  {
    variants: {
      tone: {
        neutral: 'border-border bg-muted text-muted-foreground',
        credit: 'border-financial-credit/15 bg-success-muted text-financial-credit',
        debit: 'border-financial-debit/15 bg-destructive-muted text-financial-debit',
        suspense: 'border-financial-suspense/15 bg-warning-muted text-financial-suspense',
        audit: 'border-financial-audit/15 bg-info-muted text-financial-audit'
      },
      emphasis: {
        subtle: '',
        solid: 'border-transparent text-white'
      }
    },
    compoundVariants: [
      { tone: 'neutral', emphasis: 'solid', className: 'bg-foreground text-background' },
      { tone: 'credit', emphasis: 'solid', className: 'bg-financial-credit' },
      { tone: 'debit', emphasis: 'solid', className: 'bg-financial-debit' },
      { tone: 'suspense', emphasis: 'solid', className: 'bg-financial-suspense' },
      { tone: 'audit', emphasis: 'solid', className: 'bg-financial-audit' }
    ],
    defaultVariants: { tone: 'neutral', emphasis: 'subtle' }
  }
)

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement>, VariantProps<typeof badgeVariants> {
  indicator?: boolean
}

export function Badge({ className, tone, emphasis, indicator = false, children, ...props }: BadgeProps) {
  return (
    <span className={cn(badgeVariants({ tone, emphasis }), className)} {...props}>
      {indicator && <span aria-hidden className="size-1.5 shrink-0 rounded-full bg-current" />}
      {children}
    </span>
  )
}

export { badgeVariants }
