'use client'

import * as React from 'react'

import { cn } from '@/lib/utils'

export interface WorkspaceUser {
  name: string
  initials: string
}

export interface WorkspaceHeaderProps {
  breadcrumbs: string[]
  commandLabel?: string
  commandShortcut?: string
  user: WorkspaceUser
  isDarkMode?: boolean
  isSidebarCollapsed?: boolean
  onOpenCommand?: () => void
  onToggleTheme?: () => void
  onToggleSidebar?: () => void
  onOpenProfile?: () => void
  className?: string
}

function MenuIcon() {
  return (
    <svg aria-hidden viewBox="0 0 20 20" className="size-4 fill-none stroke-current" strokeWidth="1.7">
      <path d="M3.5 5.5h13M3.5 10h13M3.5 14.5h13" strokeLinecap="round" />
    </svg>
  )
}

function SearchIcon() {
  return (
    <svg aria-hidden viewBox="0 0 20 20" className="size-4 fill-none stroke-current" strokeWidth="1.7">
      <circle cx="8.8" cy="8.8" r="4.8" />
      <path d="m12.3 12.3 4 4" strokeLinecap="round" />
    </svg>
  )
}

function ThemeIcon({ dark }: { dark: boolean }) {
  return dark ? (
    <svg aria-hidden viewBox="0 0 20 20" className="size-4 fill-none stroke-current" strokeWidth="1.7">
      <circle cx="10" cy="10" r="3.25" />
      <path d="M10 2.5v1.25M10 16.25v1.25M2.5 10h1.25M16.25 10h1.25M4.7 4.7l.9.9M14.4 14.4l.9.9M15.3 4.7l-.9.9M5.6 14.4l-.9.9" strokeLinecap="round" />
    </svg>
  ) : (
    <svg aria-hidden viewBox="0 0 20 20" className="size-4 fill-none stroke-current" strokeWidth="1.7">
      <path d="M16.4 12.4A6.4 6.4 0 0 1 7.6 3.6a6.5 6.5 0 1 0 8.8 8.8Z" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

export function WorkspaceHeader({
  breadcrumbs,
  commandLabel = 'Search or run a command',
  commandShortcut = '⌘K',
  user,
  isDarkMode = false,
  isSidebarCollapsed = false,
  onOpenCommand,
  onToggleTheme,
  onToggleSidebar,
  onOpenProfile,
  className
}: WorkspaceHeaderProps) {
  return (
    <header
      className={cn(
        'grid h-[52px] shrink-0 grid-cols-[minmax(0,1fr)_minmax(16rem,30rem)_minmax(0,1fr)] items-center gap-4 border-b bg-card px-3',
        className
      )}
    >
      <div className="flex min-w-0 items-center gap-2">
        {isSidebarCollapsed && (
          <button
            type="button"
            onClick={onToggleSidebar}
            aria-label="Show sidebar"
            className="grid size-7 shrink-0 place-items-center rounded-md text-muted-foreground hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <MenuIcon />
          </button>
        )}
        <ol aria-label="Breadcrumb" className="flex min-w-0 items-center gap-1.5 text-xs">
          {breadcrumbs.map((crumb, index) => (
            <React.Fragment key={`${crumb}-${index}`}>
              {index > 0 && <li aria-hidden className="text-muted-foreground/60">/</li>}
              <li className={cn('truncate', index === breadcrumbs.length - 1 ? 'font-semibold text-foreground' : 'text-muted-foreground')}>
                {crumb}
              </li>
            </React.Fragment>
          ))}
        </ol>
      </div>

      <button
        type="button"
        onClick={onOpenCommand}
        className="flex h-8 w-full items-center gap-2 rounded-md border bg-background px-2.5 text-xs text-muted-foreground transition-colors hover:border-input hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        <SearchIcon />
        <span className="flex-1 text-left">{commandLabel}</span>
        <kbd className="rounded border bg-muted px-1.5 py-0.5 font-sans text-[10px] font-medium leading-none text-muted-foreground">
          {commandShortcut}
        </kbd>
      </button>

      <div className="flex items-center justify-end gap-1.5">
        <button
          type="button"
          onClick={onToggleTheme}
          aria-label={isDarkMode ? 'Use light mode' : 'Use dark mode'}
          className="grid size-8 place-items-center rounded-md text-muted-foreground hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <ThemeIcon dark={isDarkMode} />
        </button>
        <div className="mx-1 h-5 w-px bg-border" />
        <button
          type="button"
          onClick={onOpenProfile}
          aria-label={`Open profile for ${user.name}`}
          className="grid size-7 place-items-center rounded-full bg-foreground text-[10px] font-semibold text-background outline-none ring-offset-2 ring-offset-background focus-visible:ring-2 focus-visible:ring-ring"
        >
          {user.initials}
        </button>
      </div>
    </header>
  )
}
