import * as React from 'react'

import { cn } from '@/lib/utils'
import { type WorkspaceHeaderProps, WorkspaceHeader } from './workspace-header'
import { type WorkspaceSidebarProps, WorkspaceSidebar } from './workspace-sidebar'

export interface WorkspaceShellProps {
  sidebar: WorkspaceSidebarProps
  header: WorkspaceHeaderProps
  children: React.ReactNode
  detailPanel?: React.ReactNode
  isDetailOpen?: boolean
  className?: string
}

export function WorkspaceShell({
  sidebar,
  header,
  children,
  detailPanel,
  isDetailOpen = false,
  className
}: WorkspaceShellProps) {
  const sidebarCollapsed = sidebar.isCollapsed ?? false
  const showDetails = Boolean(detailPanel && isDetailOpen)

  return (
    <div
      className={cn(
        'grid h-dvh min-h-[42rem] overflow-hidden bg-background transition-[grid-template-columns] duration-200 ease-out',
        sidebarCollapsed ? 'grid-cols-[0_minmax(0,1fr)]' : 'grid-cols-[16rem_minmax(0,1fr)]',
        className
      )}
    >
      <div className="min-w-0 overflow-hidden">
        <WorkspaceSidebar {...sidebar} />
      </div>

      <div className="flex min-w-0 flex-col overflow-hidden">
        <WorkspaceHeader {...header} isSidebarCollapsed={sidebarCollapsed} />
        <div
          className={cn(
            'grid min-h-0 flex-1 transition-[grid-template-columns] duration-200 ease-out',
            showDetails ? 'grid-cols-[minmax(0,1fr)_24rem]' : 'grid-cols-[minmax(0,1fr)_0rem]'
          )}
        >
          <main className="min-w-0 overflow-auto">{children}</main>
          <div className="min-w-0 overflow-hidden">{detailPanel}</div>
        </div>
      </div>
    </div>
  )
}
