'use client'

import * as React from 'react'

import { cn } from '@/lib/utils'

export interface ContextualSheetProps {
  title: string
  description?: string
  isOpen: boolean
  onClose?: () => void
  children: React.ReactNode
  footer?: React.ReactNode
  className?: string
}

export function ContextualSheet({
  title,
  description,
  isOpen,
  onClose,
  children,
  footer,
  className
}: ContextualSheetProps) {
  return (
    <aside
      aria-label={title}
      aria-hidden={!isOpen}
      className={cn(
        'flex h-full min-w-[24rem] flex-col border-l bg-card transition-[opacity,transform] duration-200 ease-out',
        isOpen ? 'translate-x-0 opacity-100' : 'translate-x-4 opacity-0',
        className
      )}
    >
      <div className="flex min-h-[60px] shrink-0 items-start gap-3 border-b px-4 py-3">
        <div className="min-w-0 flex-1">
          <h2 className="truncate text-sm font-semibold">{title}</h2>
          {description && <p className="mt-0.5 truncate text-xs text-muted-foreground">{description}</p>}
        </div>
        <button
          type="button"
          onClick={onClose}
          className="grid size-7 shrink-0 place-items-center rounded-md text-muted-foreground hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          aria-label="Close details"
        >
          <svg aria-hidden viewBox="0 0 20 20" className="size-4 fill-none stroke-current" strokeWidth="1.7">
            <path d="m5 5 10 10M15 5 5 15" strokeLinecap="round" />
          </svg>
        </button>
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto">{children}</div>
      {footer && <div className="shrink-0 border-t p-3">{footer}</div>}
    </aside>
  )
}
